import AVFoundation
import XCTest

/// 진단: 22.05kHz MPEG-2 MP3(게임 효과음과 같은 형식)를 맥이 몇 Hz로 읽는지
final class AudioFormatTests: XCTestCase {
    /// ffmpeg로 만든 440Hz 1초 사인파 (22.05kHz, 모노, 24kbps, 태그 없음)
    static let sine = ""

    func testMPEG2SampleRate() throws {
        let data = Data(base64Encoded: Self.sine)!
        if let p = try? AVAudioPlayer(data: data, fileTypeHint: AVFileType.mp3.rawValue) {
            print("AUDIOCHECK data+mp3hint rate=\(p.format.sampleRate) duration=\(p.duration)")
        } else { print("AUDIOCHECK data+mp3hint failed") }
        if let p = try? AVAudioPlayer(data: data) {
            print("AUDIOCHECK data rate=\(p.format.sampleRate) duration=\(p.duration)")
        } else { print("AUDIOCHECK data failed") }
        let url = FileManager.default.temporaryDirectory.appendingPathComponent("audiocheck.mp3")
        try data.write(to: url)
        if let p = try? AVAudioPlayer(contentsOf: url) {
            print("AUDIOCHECK file rate=\(p.format.sampleRate) duration=\(p.duration)")
        } else { print("AUDIOCHECK file failed") }
        if let f = try? AVAudioFile(forReading: url) {
            print("AUDIOCHECK avaudiofile rate=\(f.fileFormat.sampleRate) frames=\(f.length)")
        } else { print("AUDIOCHECK avaudiofile failed") }
    }
}
